func (p Point) add(q Point) Point {
	return Point{p.x + q.x, p.y + q.y}
}

func (p Point) sub(q Point) Point {
	return Point{p.x - q.x, p.y - q.y}
}

func (p Point) mul(v float64) Point {
	return Point{p.x * v, p.y * v}
}

func (p Point) div(v float64) Point {
	return p.mul(1.0 / v)
}

func (p Point) rot90() Point {
	return Point{-p.y, p.x}
}

func pToV(a, b Point) Vec {
	return Vec{b.x - a.x, b.y - a.y}
}

func dMult(a, b Vec) float64 {
	return a.x*b.x + a.y*b.y
}

func xMult(a, b Vec) float64 {
	return a.x*b.y - a.y*b.x
}

func vecMod(a Vec) float64 {
	return math.Sqrt(dMult(a, a))
}

func vecMod2(a Vec) float64 {
	return dMult(a, a)
}

func corner2V(a, b Vec) float64 {
	return math.Abs(math.Acos(dMult(a, b) / vecMod(a) / vecMod(b)))
}

func vecUnit(a Vec) Vec {
	return a.div(vecMod(a))
}

func vRotate(v Vec, alpha float64) Vec {
	sa, ca := math.Sin(alpha), math.Cos(alpha)
	return Vec{v.x*ca - v.y*sa, v.x*sa + v.y*ca}
}

func pRotate(p, o Point, alpha float64) Point {
	return o.add(vRotate(pToV(o, p), alpha))
}

func getVV(v Vec) Vec {
	return vRotate(v, math.Pi/2)
}

func shadowPOnLine(p, a, b Point) Point {
	ab := pToV(a, b)
	ap := pToV(a, p)
	projection := vecUnit(ab).mul(dMult(ab, ap) / vecMod(ab))
	return a.add(projection)
}

func lineCrossCircle(a, b, o Point, r float64) []Point {
	ret := make([]Point, 0, 2)
	t := shadowPOnLine(o, a, b)
	ot := pToV(o, t)
	d := vecMod(ot)

	if d-r > eps {
		return ret
	}
	if math.Abs(d-r) < eps {
		return append(ret, t)
	}

	lr := math.Sqrt(r*r - vecMod2(ot))
	ta := t.add(vecUnit(pToV(t, a)).mul(lr))
	tb := t.add(vecUnit(pToV(t, b)).mul(lr))
	return append(ret, ta, tb)
}

func pointTangentCircle(p, o Point, r float64) []Point {
	x2 := vecMod2(p.sub(o))
	d2 := x2 - r*r
	ret := make([]Point, 0, 2)

	if d2 < -eps {
		return ret
	}
	if r <= eps {
		return append(ret, o, o)
	}

	d2 = math.Max(d2, 0)
	q1 := o.add(p.sub(o).mul(r * r / x2))
	q2 := p.sub(o).rot90().mul(-r * math.Sqrt(d2) / x2)
	return append(ret, q1.sub(q2), q1.add(q2))
}

func pOnSeg(p, a, b Point) bool {
	if math.Abs(xMult(pToV(a, b), pToV(a, p))) > eps {
		return false
	}
	if math.Min(a.x, b.x) > p.x || p.x > math.Max(a.x, b.x) {
		return false
	}
	if math.Min(a.y, b.y) > p.y || p.y > math.Max(a.y, b.y) {
		return false
	}
	return true
}

func pDisLine(p, a, b Point) float64 {
	return vecMod(shadowPOnLine(p, a, b).sub(p))
}

var (
	p, s       Point
	vp, vs, r  float64
	sita       float64
)

func check(t float64) bool {
	lenOR := vecMod(p)
	e := Point{
		lenOR * math.Cos(sita+t*vp/lenOR),
		lenOR * math.Sin(sita+t*vp/lenOR),
	}

	ccp := lineCrossCircle(s, e, Point{}, r)
	if len(ccp) != 2 || (!pOnSeg(ccp[0], s, e) && !pOnSeg(ccp[1], s, e)) {
		return vs*t > vecMod(e.sub(s))
	}

	ttp1 := pointTangentCircle(s, Point{}, r)
	if pDisLine(ttp1[0], s, e) > pDisLine(ttp1[1], s, e) {
		ttp1[0], ttp1[1] = ttp1[1], ttp1[0]
	}

	ttp2 := pointTangentCircle(e, Point{}, r)
	if pDisLine(ttp2[0], s, e) > pDisLine(ttp2[1], s, e) {
		ttp2[0], ttp2[1] = ttp2[1], ttp2[0]
	}

	alpha := corner2V(pToV(Point{}, ttp1[0]), pToV(Point{}, ttp2[0]))

	return vecMod(pToV(s, ttp1[0]))+
		vecMod(pToV(e, ttp2[0]))+
		alpha*r < vs*t
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	for {
		if _, err := fmt.Fscan(in, &p.x, &p.y, &vp, &s.x, &s.y, &vs, &r); err != nil {
			break
		}

		sita = math.Acos(p.x / vecMod(p))
		if p.y < 0 {
			sita = -sita
		}

		left, right := 0.0, 1e10
		for math.Abs(left-right) > 1e-12 {
			mid := (left + right) * 0.5
			if check(mid) {
				right = mid
			} else {
				left = mid
			}
		}

		fmt.Fprintf(out, "%.9f\n", left)
	}
}

